    n = len(A)
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if A[i] < A[j]:
                dp[i] = dp[j]
            else:
                dp[i] = dp[j] + 1
    return max(dp[n - 1] for n in range(1, n + 1))

