def distance(s, k):
    min_dist = {}
    for i in range(len(s)):
        for j in range(len(s[i])):
            if s[i] == s[j]:
                min_dist[i][j] = min(min_dist[i-1][j], min_dist[i][j-1])
            else:
                min_dist[i][j] = min(min_dist[i-1][j], min_dist[i][j-1])
    return min_dist[k]

def minMedian(nums, k):
    if len(nums) == len(nums[0]) or nums[0] == k:
        return 0
    else:
        for i in range(1, len(nums)):
            if nums[i] > nums[i - 1]:
                nums[i] = nums[i - 1]
            else:
                nums[i] = nums[i - 1]
        return nums[k]

