def sieve(n):
    sieve = [True] * (n+1)
    sieve[0] = sieve[1] = False
    for i in range(2, n+1):
        if sieve[i]:
            sieve[i] = False
    return sieve

def max_distance(nums):
    primes = sieve(nums)
    primes[0] = True
    for i in range(1, len(primes)):
        if primes[i]:
            primes[i] = False
    return primes[0]

def min_amount(coins, k):
    dp = [[0] * (k + 1) for _ in range(k)]
    for i in range(len(coins)):
        for j in range(i + 1, len(coins)):
            if coins[i] == coins[j]:
                dp[i][j] = coins[i]
            else:
                dp[i][j] = coins[i] + coins[j]
    return dp[k][-1]

